package com.bank.settlement.model;

import java.math.BigDecimal;

// A simple, auditable result: the two one-based positions and their amounts.
public class PairResult {
    private final int firstIndex;
    private final int secondIndex;
    private final BigDecimal firstAmount;
    private final BigDecimal secondAmount;
    private final boolean found;

    public PairResult(int firstIndex, int secondIndex,
                      BigDecimal firstAmount, BigDecimal secondAmount, boolean found) {
        this.firstIndex = firstIndex;
        this.secondIndex = secondIndex;
        this.firstAmount = firstAmount;
        this.secondAmount = secondAmount;
        this.found = found;
    }

    public static PairResult notFound() {
        return new PairResult(-1, -1, null, null, false);
    }

    public boolean isFound() { return found; }
    public int getFirstIndex() { return firstIndex; }
    public int getSecondIndex() { return secondIndex; }
    public BigDecimal getFirstAmount() { return firstAmount; }
    public BigDecimal getSecondAmount() { return secondAmount; }

    @Override
    public String toString() {
        if (!found) return "PairResult{found=false}";
        return "PairResult{pos " + firstIndex + " (" + firstAmount + ") + pos "
                + secondIndex + " (" + secondAmount + ")}";
    }
}
