package com.bank.settlement.service;

import com.bank.settlement.model.PairResult;
import java.math.BigDecimal;
import java.util.logging.Logger;

// Finds two settlement amounts (in a sorted list) that add up to a target.
public class SettlementPairFinder {
    private static final Logger log = Logger.getLogger(SettlementPairFinder.class.getName());

    // Precondition: amounts is sorted ascending. Returns one-based positions.
    public PairResult findPair(BigDecimal[] amounts, BigDecimal target) {
        if (amounts == null || amounts.length < 2) {
            log.warning("Need at least two amounts to form a pair.");
            return PairResult.notFound();
        }
        int left = 0;
        int right = amounts.length - 1;

        while (left < right) {
            BigDecimal sum = amounts[left].add(amounts[right]);
            int cmp = sum.compareTo(target);
            if (cmp == 0) {
                log.info(() -> "Pair found at positions " + (1) + "/" + (1)); // info event
                return new PairResult(left + 1, right + 1, amounts[left], amounts[right], true);
            } else if (cmp > 0) {
                right--;              // sum too big, shrink from the large end
            } else {
                left++;               // sum too small, grow from the small end
            }
        }
        log.warning("No pair of settlements adds up to the target.");
        return PairResult.notFound();
    }
}
