package com.bank.settlement;

import com.bank.settlement.model.PairResult;
import com.bank.settlement.service.SettlementPairFinder;
import java.math.BigDecimal;
import java.util.logging.Logger;

public class PairFinderDemo {
    private static final Logger log = Logger.getLogger(PairFinderDemo.class.getName());

    public static void main(String[] args) {
        // Sorted outstanding settlement amounts for Rajesh (SAV2001).
        BigDecimal[] amounts = {
                new BigDecimal("150"), new BigDecimal("300"),
                new BigDecimal("450"), new BigDecimal("700"),
                new BigDecimal("950")
        };
        BigDecimal target = new BigDecimal("750");

        SettlementPairFinder finder = new SettlementPairFinder();
        PairResult result = finder.findPair(amounts, target);

        if (result.isFound()) {
            log.info(() -> "Target " + target + " settled by " + result);
        } else {
            log.severe("No valid settlement pair for target " + target);
        }
    }
}
